import numpy as np, wave, sys
def load(fn):
    w=wave.open(fn,'rb'); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2')
    if w.getnchannels()==2: d=d.reshape(-1,2)
    else: d=d.reshape(-1,1)
    return d.astype(float)
def pitch(mono, lo=40, hi=4000):
    seg=mono[4000:44000].copy()
    if len(seg)<2000: seg=mono.copy()
    seg-=seg.mean()
    win=np.hanning(len(seg))
    sp=np.abs(np.fft.rfft(seg*win)); fr=np.fft.rfftfreq(len(seg),1/44100)
    band=(fr>=lo)&(fr<=hi)
    i=np.argmax(sp[band])
    idxs=np.where(band)[0]; k=idxs[i]
    # parabolic interp
    if 1<=k<len(sp)-1:
        a,b,c=sp[k-1],sp[k],sp[k+1]
        d=0.5*(a-c)/(a-2*b+c+1e-12)
    else: d=0
    return (k+d)*44100/len(seg)
if __name__=='__main__':
    d=load(sys.argv[1])
    print(round(pitch(d[:,0]),1))
